/*Extra bits*/
.qiB > div {
    background-color: rgb(255 255 255 / 0%) !important;
} /*White bit behind suggestion buttons on home page*/

body {
    background-image: url(https://wallpaperaccess.com/full/2081927.jpg)!important; /*Background*/
    background-repeat: no-repeat !important;
    background-attachment: fixed;
    background-position: center;
    background-blend-mode: screen !important;
    background-size: cover !important;
}

input[name="searchBoxInput"] { /*Searcbox text*/
    color: #0c0 !important;
}

.Jea.KS5.wsz.zI7.iyn.Hsu { /*Bottom bar on logged-out page*/
    background: #050 !important;
}

#searchBoxContainer > div {
    background-color: var(--g-colorGray0) !important;
}
#searchBoxContainer > div > div[style*=box-shadow] {
    box-shadow: none !important;
    background-color: var(--g-colorRed100) !important;
}

/*"More" button on pin pages*/
.FNs.XiG.zI7.iyn.Hsu {
    background: #fff0 !important;
}

